import { IMediaStore } from '@/features/alumni-stories/domain/interfaces';
import { randomUUID } from 'node:crypto';
import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, rename, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import 'server-only';

// Keys are generated by the app, never taken from users; this only guards
// against a programming error escaping the media root.
const KEY_PATTERN = /^[a-z0-9][a-z0-9_-]*(\/[a-z0-9][a-z0-9._-]*)*$/;

export class LocalMediaStore implements IMediaStore {
  constructor(private readonly root: string) {}

  async put(key: string, body: ReadableStream<Uint8Array>) {
    const target = this.resolve(key);
    await mkdir(path.dirname(target), { recursive: true });

    // Write beside the target, then rename: a crash mid-write never leaves a
    // truncated file under a real key.
    const temp = `${target}.${randomUUID()}.partial`;
    let sizeBytes = 0;
    const counter = new Transform({
      transform(chunk: Buffer, _encoding, callback) {
        sizeBytes += chunk.length;
        callback(null, chunk);
      },
    });

    try {
      await pipeline(
        // Iterate the web stream directly: Readable.fromWeb does not pass a
        // source error on under Bun, which would hang a dropped upload.
        body as unknown as AsyncIterable<Uint8Array>,
        counter,
        createWriteStream(temp, { flags: 'wx' })
      );
      await rename(temp, target);
    } catch (error) {
      await rm(temp, { force: true });
      throw error;
    }

    return { sizeBytes };
  }

  async stat(key: string) {
    try {
      const info = await stat(this.resolve(key));
      return { sizeBytes: info.size };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
  }

  async read(key: string, range?: { start: number; end: number }) {
    const stream = createReadStream(this.resolve(key), range);
    // Surface a missing file as a rejected promise rather than a stream error.
    await new Promise<void>((resolve, reject) => {
      stream.once('open', () => resolve());
      stream.once('error', reject);
    });
    return Readable.toWeb(stream) as unknown as ReadableStream<Uint8Array>;
  }

  async delete(key: string) {
    await rm(this.resolve(key), { force: true });
  }

  async deletePrefix(prefix: string) {
    await rm(this.resolve(prefix), { recursive: true, force: true });
  }

  private resolve(key: string) {
    if (!KEY_PATTERN.test(key) || key.includes('..')) {
      throw new Error(`Invalid media key: ${key}`);
    }
    return path.join(this.root, ...key.split('/'));
  }
}
